      "caption": "Routing - hash-based filter navigation and persistence",
      "scenarios": [
        "features/routing.feature:Show all todos by default",
        "features/routing.feature:All filter link is selected by default",
        "features/routing.feature:Filter active todos",
        "features/routing.feature:Filter completed todos",
